    private void initNMS() throws Exception {
        initNMS(SystemService.PHASE_BOOT_COMPLETED);
    }

    @SuppressLint("MissingPermission")
    private void initNMS(int upToBootPhase) throws Exception {
        mService = new TestableNotificationManagerService(mContext, mTestableLooper);

        // apps allowed as convos
        mService.setStringArrayResourceValue(PKG_O);

        TestableResources tr = mContext.getOrCreateTestableResources();
        tr.addOverride(com.android.internal.R.string.config_defaultSearchSelectorPackageName,
                SEARCH_SELECTOR_PKG);
        tr.addOverride(R.array.config_notificationDefaultUnsupportedAdjustments,
                new String[] {KEY_TYPE});

        doAnswer(invocation -> {
            mOnPermissionChangeListener = invocation.getArgument(2);
            return null;
        }).when(mAppOpsManager).startWatchingMode(eq(AppOpsManager.OP_POST_NOTIFICATION), any(),
                any());
        when(mUmInternal.isUserInitialized(anyInt())).thenReturn(true);

        mWorkerHandler = spy(mService.new WorkerHandler(mTestableLooper.getLooper()));
        mBroadcastsHandler = new Handler(mTestableLooper.getLooper());
        mGroupHelper = spy(mService.getGroupHelper());

        mRankingHandler = spy(mService.new RankingHandlerWorker(mTestableLooper.getLooper()));

        mService.init(mWorkerHandler, mRankingHandler, mBroadcastsHandler, mPackageManager,
                mPackageManagerClient, mLightsManager, mListeners,
                spy(mService.new NotificationAssistants(mContext, mPackageManager)),
                mConditionProviders,
                mCompanionMgr, mSnoozeHelper, mUsageStats, mPolicyFile, mRulesFile,
                mActivityManager, mGroupHelper, mAm, mAtm, mAppUsageStats, mDevicePolicyManager,
                mUgm, mUgmInternal, mAppOpsManager, mHistoryManager, mStatsManager, mAmi,
                mToastRateLimiter, mPermissionHelper, mock(UsageStatsManagerInternal.class),
                mTelecomManager, mLogger, mTestFlagResolver, mPermissionManager, mPowerManager,
                mPostNotificationTrackerFactory, mUiEventLogger, mBitmapOffloader,
                new NotificationListenerStats(MAX_CHANNELS_CREATED_BY_NLS_FOR_TESTING),
                mNotificationRecordLogger, mNotificationInstanceIdSequence,
                new TestPreferencesHelperFactory());

        mAssistants = mService.mAssistants;
        mService.mDefaultUnsupportedAdjustments = new String[]{};
        when(mAssistant.asBinder()).thenReturn(mock(IBinder.class));
        when(mAssistantManagedProfile.asBinder()).thenReturn(mock(IBinder.class));
        mAssistants.registerSystemService(mAssistant, mAssistantComponent, mZero.id, 1000);
        mAssistantInfo = mAssistants.checkServiceTokenLocked(mAssistant);
        when(mListeners.checkServiceTokenLocked(mAssistant)).thenReturn(mAssistantInfo);
        mAssistants.registerSystemService(mAssistantManagedProfile,
                mAssistantComponent, mZeroManagedProfile.id, 1000);
        mAssistantManagedProfileInfo =
                mAssistants.checkServiceTokenLocked(mAssistantManagedProfile);
        // some tests verify counts about updating defaults for the assistant, so ignore counts that
        // happen in init()
        Mockito.clearInvocations(mAssistants);

        mService.setAttentionHelper(mAttentionHelper);
        mService.setLockPatternUtils(mock(LockPatternUtils.class));

        // make sure PreferencesHelper doesn't try to interact with any real caches
        PreferencesHelper prefHelper = spy(mService.mPreferencesHelper);
        doNothing().when(prefHelper).invalidateNotificationChannelCache();
        doNothing().when(prefHelper).invalidateNotificationChannelGroupCache();
        mService.setPreferencesHelper(prefHelper);

        // Return first true for RoleObserver main-thread check
        when(mMainLooper.isCurrentThread()).thenReturn(true).thenReturn(false);
        ModuleInfo moduleInfo = new ModuleInfo();
        moduleInfo.setApexModuleName(ADSERVICES_MODULE_PKG);
        moduleInfo.setApkInApexPackageNames(List.of(ADSERVICES_APK_PKG));
        when(mPackageManagerClient.getInstalledModules(anyInt()))
                .thenReturn(List.of(moduleInfo));
        if (upToBootPhase >= SystemService.PHASE_SYSTEM_SERVICES_READY) {
            mService.onBootPhase(SystemService.PHASE_SYSTEM_SERVICES_READY, mMainLooper);
        }

        Mockito.reset(mHistoryManager);
        verify(mHistoryManager, never()).onBootPhaseAppsCanStart();

        if (upToBootPhase >= SystemService.PHASE_THIRD_PARTY_APPS_CAN_START) {
            mService.onBootPhase(SystemService.PHASE_THIRD_PARTY_APPS_CAN_START, mMainLooper);
            verify(mHistoryManager).onBootPhaseAppsCanStart();
        }

        mStrongAuthTracker = mService.new StrongAuthTrackerFake(mContext);
        mService.setStrongAuthTracker(mStrongAuthTracker);

        mShortcutHelper = mService.getShortcutHelper();
        mShortcutHelper.setLauncherApps(mLauncherApps);
        mShortcutHelper.setShortcutServiceInternal(mShortcutServiceInternal);
        mShortcutHelper.setUserManager(mUserManager);

        // Capture PackageIntentReceiver
        ArgumentCaptor<BroadcastReceiver> broadcastReceiverCaptor =
                ArgumentCaptor.forClass(BroadcastReceiver.class);
        ArgumentCaptor<IntentFilter> intentFilterCaptor =
                ArgumentCaptor.forClass(IntentFilter.class);

        verify(mContext, atLeastOnce()).registerReceiverAsUser(broadcastReceiverCaptor.capture(),
                any(), intentFilterCaptor.capture(), any(), any());
        verify(mContext, atLeastOnce()).registerReceiver(broadcastReceiverCaptor.capture(),
                intentFilterCaptor.capture(), anyInt());
        verify(mContext, atLeastOnce()).registerReceiver(broadcastReceiverCaptor.capture(),
                intentFilterCaptor.capture());
        List<BroadcastReceiver> broadcastReceivers = broadcastReceiverCaptor.getAllValues();
        List<IntentFilter> intentFilters = intentFilterCaptor.getAllValues();

        for (int i = 0; i < intentFilters.size(); i++) {
            final IntentFilter filter = intentFilters.get(i);
            if (filter.hasAction(Intent.ACTION_DISTRACTING_PACKAGES_CHANGED)
                    && filter.hasAction(Intent.ACTION_PACKAGES_UNSUSPENDED)
                    && filter.hasAction(Intent.ACTION_PACKAGES_SUSPENDED)) {
                mPackageIntentReceiver = broadcastReceivers.get(i);
            }
            if (filter.hasAction(Intent.ACTION_USER_STOPPED)
                    || filter.hasAction(Intent.ACTION_USER_SWITCHED)
                    || filter.hasAction(Intent.ACTION_PROFILE_UNAVAILABLE)
                    || filter.hasAction(Intent.ACTION_MANAGED_PROFILE_UNAVAILABLE)) {
                // There may be multiple receivers, get the NMS one
                if (broadcastReceivers.get(i).toString().contains(
                        NotificationManagerService.class.getName())) {
                    mUserIntentReceiver = broadcastReceivers.get(i);
                }
            }
            if (filter.hasAction(ACTION_NOTIFICATION_TIMEOUT)
                    && filter.hasDataScheme(SCHEME_TIMEOUT)) {
                mNotificationTimeoutReceiver = broadcastReceivers.get(i);
            }
        }
        assertNotNull("package intent receiver should exist", mPackageIntentReceiver);
        assertNotNull("User receiver should exist", mUserIntentReceiver);

        // Pretend the shortcut exists
        List<ShortcutInfo> shortcutInfos = new ArrayList<>();
        shortcutInfos.add(createMockConvoShortcut());
        when(mLauncherApps.getShortcuts(any(), any())).thenReturn(shortcutInfos);
        when(mShortcutServiceInternal.isSharingShortcut(anyInt(), anyString(), anyString(),
                anyString(), anyInt(), any())).thenReturn(true);
        when(mUserManager.isUserUnlocked(any(UserHandle.class))).thenReturn(true);
        mockIsUserVisible(DEFAULT_DISPLAY, true);
        mockIsVisibleBackgroundUsersSupported(false);

        // Set the testable bubble extractor
        RankingHelper rankingHelper = mService.getRankingHelper();
        BubbleExtractor extractor = rankingHelper.findExtractor(BubbleExtractor.class);
        extractor.setActivityManager(mActivityManager);

        // Tests call directly into the Binder.
        mBinderService = mService.getBinderService();
        mInternalService = mService.getInternalService();

        mBinderService.createNotificationChannels(mPkg, new ParceledListSlice(
                Arrays.asList(mTestNotificationChannel, mSilentChannel, mMinChannel)));
        mBinderService.createNotificationChannels(PKG_P, new ParceledListSlice(
                Arrays.asList(mTestNotificationChannel, mSilentChannel, mMinChannel)));
        mBinderService.createNotificationChannels(PKG_O, new ParceledListSlice(
                Arrays.asList(mTestNotificationChannel, mSilentChannel, mMinChannel)));
        assertNotNull(mBinderService.getNotificationChannel(
                mPkg, mContext.getUserId(), mPkg, TEST_CHANNEL_ID));
        assertNotNull(mBinderService.getNotificationChannel(
                mPkg, mContext.getUserId(), mPkg, mSilentChannel.getId()));
        assertNotNull(mBinderService.getNotificationChannel(
                mPkg, mContext.getUserId(), mPkg, mMinChannel.getId()));
        clearInvocations(mRankingHandler);
        when(mPermissionHelper.hasPermission(anyInt())).thenReturn(true);

        var checker = mock(TestableNotificationManagerService.ComponentPermissionChecker.class);
        mService.permissionChecker = checker;
        when(checker.check(anyString(), anyInt(), anyInt(), anyBoolean()))
                .thenReturn(PackageManager.PERMISSION_DENIED);
    }

    @After
    public void assertNotificationRecordLoggerCallsValid() {
        waitForIdle(); // Finish async work, including all logging calls done by Runnables.
        for (NotificationRecordLoggerFake.CallRecord call : mNotificationRecordLogger.getCalls()) {
            if (call.wasLogged) {
                assertNotNull(call.event);
                if (call.event == NOTIFICATION_POSTED || call.event == NOTIFICATION_UPDATED) {
                    assertThat(call.postDurationMillisLogged).isGreaterThan(0);
                } else {
                    assertThat(call.postDurationMillisLogged).isNull();
                }
            }
        }
        assertThat(mNotificationRecordLogger.getPendingLogs()).isEmpty();
    }

    @After
    public void assertAllTrackersFinishedOrCancelled() {
        waitForPost(); // Finish async work.
        // Verify that no trackers were left dangling.
        for (PostNotificationTracker tracker : mPostNotificationTrackerFactory.mCreatedTrackers) {
            assertWithMessage(tracker.mKey + "  is ongoing").that(tracker.isOngoing()).isFalse();
        }
        mPostNotificationTrackerFactory.mCreatedTrackers.clear();
    }

    @After
    public void assertAllWakeLocksReleased() {
        waitForPost(); // Finish async work.
        for (WakeLock wakeLock : mAcquiredWakeLocks) {
            assertThat(wakeLock.isHeld()).isFalse();
        }
    }

    @After
    public void tearDown() throws Exception {
        if (mFile != null) mFile.delete();

        if (mActivityIntent != null) {
            mActivityIntent.cancel();
        }

        if (mService != null) {
            mService.clearNotifications();
        }
        if (mTestableLooper != null) {
            mTestableLooper.processAllMessages();
        }

        try {
            mService.onDestroy();
        } catch (Exception e) {
            Log.e(TAG, "failed to destroy", e);
            // can throw if a broadcast receiver was never registered
        }

        InstrumentationRegistry.getInstrumentation()
                .getUiAutomation().dropShellPermissionIdentity();
        if (mWorkerHandler != null) {
            // Remove scheduled messages that would be processed when the test is already done, and
            // could cause issues, for example, messages that remove/cancel shown toasts (this causes
            // problematic interactions with mocks when they're no longer working as expected).
            mWorkerHandler.removeCallbacksAndMessages(null);
        }
        if (mBroadcastsHandler != null) {
            mBroadcastsHandler.removeCallbacksAndMessages(null);
        }

        if (mTestableLooper != null) {
            // Must remove static reference to this test object to prevent leak (b/261039202)
            mTestableLooper.remove(this);
        }
    }

