            mService.new PostNotificationRunnable(r.getKey(), r.getSbn().getPackageName(),
                    r.getUid(),
                    mPostNotificationTrackerFactory.newTracker(null, r.getKey())).run();
            waitForIdle();

            r.setBundleType(adjustmentType);
