        Bundle signals = new Bundle();
        signals.putInt(KEY_TYPE, TYPE_PROMOTION);
        Adjustment adjustment = new Adjustment(r2.getSbn().getPackageName(), r2.getKey(), signals,
                "", r2.getUser().getIdentifier());
